+namespace sv_95f7dc36b77b4828b70affc204937037.Services;
+
+/// <summary>
+/// Scoped service that manages low-stock alert polling for the current user circuit.
+/// Exposes an event so all subscribed components update when new data arrives.
+/// </summary>
+public sealed class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private readonly Random _random = new();
+    private Timer? _timer;
+    private int _subscriberCount;
+
+    public int LatestLowStockCount { get; private set; }
+
+    /// <summary>
+    /// Fired on the thread-pool when new alert data arrives.
+    /// Subscribers must marshal to their own sync context (e.g., InvokeAsync).
+    /// </summary>
+    public event Func<Task>? OnAlertDataChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+    }
+
+    /// <summary>
+    /// Simulates a database query returning low-stock item count for a warehouse.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        // Simulate async DB call returning 0–15
+        var count = _random.Next(0, 16);
+        return Task.FromResult(count);
+    }
+
+    /// <summary>
+    /// Call when a component wants polling to be active.
+    /// Polling starts on first subscriber, stops when all unsubscribe.
+    /// </summary>
+    public void StartPolling()
+    {
+        _subscriberCount++;
+        if (_timer is null)
+        {
+            _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
+        }
+    }
+
+    /// <summary>
+    /// Call when a component no longer needs polling (e.g., on dispose).
+    /// </summary>
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+        if (_subscriberCount == 0)
+        {
+            _timer?.Dispose();
+            _timer = null;
+        }
+    }
+
+    private async void PollCallback(object? state)
+    {
+        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+        LatestLowStockCount = count;
+
+        if (OnAlertDataChanged is not null)
+        {
+            await OnAlertDataChanged.Invoke();
+        }
+    }
+
+    public void Dispose()
+    {
+        _timer?.Dispose();
+        _timer = null;
+    }
+}
+

