@rendermode InteractiveServer
@using sv_95f7dc36b77b4828b70affc204937037.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            @GetWarehouseName(WarehouseState.CurrentWarehouseId)
            <span class="text-muted fs-6">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LatestLowStockCount == 0)
            {
                <span class="text-success fs-4">✅ All stock levels OK</span>
            }
            else
            {
                <span class="text-warning fs-4">
                    ⚠️ <strong>@AlertService.LatestLowStockCount</strong> item(s) below minimum level
                </span>
            }
        </p>
        <small class="text-muted">Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        AlertService.StartPolling();
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertDataChanged()
    {
        _lastUpdate = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private static string GetWarehouseName(string id)
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        AlertService.StopPolling();
    }
}

